pub fn check_core_ops_coalesce<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, value: &Expr, fallback: &Expr, span: &Span) -> Ty {
    let outer = state.flow.read_a_map;
    state.flow.read_a_map = false;
    let lending = state.flow.lending_let;
    state.flow.lending_let = false;
    let left = check_core_expr(state, world, host, value, span);
    let read_now = state.flow.read_a_map;
    state.flow.read_a_map = outer;
    if state.nothing_to_fall_back_from(world, value, &left, expr, span) {
        let (walked, handed) = state.taken_so_far();
        check_core_expr(state, world, host, fallback, span);
        state.walked.truncate(nikaia_std::count::of(walked));
        state.handed.truncate(nikaia_std::count::of(handed));
        return left;
    }
    let from_a_map = check_core_ops_from_a_map(&state, world, value, read_now);
    let from = state.taken_so_far();
    state.flow.lending_let = lending;
    let other = check_core_expr(state, world, host, fallback, span);
    state.flow.lending_let = false;
    let leaves = state.leaves(world, fallback);
    state.a_branch_that_leaves(from, leaves, span);
    let nullable = check_core_ops_nullable(&left);
    let inner = check_core_ops_inside(&left);
    let place = check_core_ops_place(value);
    if from_a_map && nullable && moves(&inner) && state.jumps(world, fallback) { state.facts.map_read_views.insert(id_of(expr) as i64); }
    if nullable && leaves && check_core_ops_a_word(&inner) && (check_core_stmt_an_index(value) || check_core_stmt_a_get(world, value)) { state.facts.copied_jump_reads.insert(id_of(expr) as i64); }
    if lending && !from_a_map && check_core_ops_index(value) && (state.jumps(world, fallback) || state.facts.lent_coalesces.contains_key(&(id_of(fallback) as i64))) && nullable && state.takes_away(world, &inner.unseen()) {
        if check_core_ops_plain_text(&inner) { state.facts.lent_coalesces.insert(id_of(expr) as i64, String::from(".as_deref()")); } else { state.facts.lent_coalesces.insert(id_of(expr) as i64, String::from(".as_ref()")); }
        return view_of_type(&inner);
    }
    if place && state.jumps(world, fallback) && nullable && state.takes_away(world, &inner.unseen()) && (check_core_ops_lent_root(&state, world, value) || check_core_ops_behind_a_view(&state, world, value)) {
        if check_core_ops_plain_text(&inner) { state.facts.lent_coalesces.insert(id_of(expr) as i64, String::from(".as_deref()")); } else { state.facts.lent_coalesces.insert(id_of(expr) as i64, String::from(".as_ref()")); }
        return view_of_type(&inner);
    }
    if place && nullable && check_core_ops_plain_text(&inner) && check_core_ops_lit_str(fallback) && check_core_ops_behind_a_view(&state, world, value) {
        state.facts.lent_coalesces.insert(id_of(expr) as i64, String::from(".as_deref()"));
        state.facts.view_fallbacks.insert(id_of(fallback) as i64);
        return check_core_ops_view("str");
    }
    if place {
        let opened: Option<String> = state.a_coalesce_that_may_lend(world, &left, fallback, &other);
        if opened.is_some() { state.flow.pending_coalesces.push(CheckPendingCoalesce { key: id_of(expr) as i64, left: id_of(value) as i64, ty: left.clone(), span: Span { start: span.start, end: span.end }, opened: nikaia_std::index::or(opened.as_deref(), || "").to_owned() }); } else { state.hands_over(world, value, &left, "given to `??`", span); }
    }
    if nullable && check_core_ops_lit_str(fallback) {
        if inner == check_core_ops_view("str") { state.facts.view_fallbacks.insert(id_of(fallback) as i64); }
        if inner == check_core_ops_named("String") && from_a_map {
            state.facts.view_fallbacks.insert(id_of(fallback) as i64);
            return check_core_ops_view("str");
        }
        if inner == check_core_ops_named("String") && !from_a_map && check_core_ops_index(value) {
            state.facts.view_fallbacks.insert(id_of(fallback) as i64);
            state.facts.lent_list_reads.insert(id_of(expr) as i64);
            return check_core_ops_view("str");
        }
    }
    if nullable && !from_a_map && check_core_ops_view_of_a_list(&inner) && check_core_ops_empty_list(fallback) {
        state.facts.view_fallbacks.insert(id_of(fallback) as i64);
        return inner;
    }
    if nullable && inner == check_core_ops_named("String") && from_a_map && other.is_a_view() && check_core_ops_place(fallback) && check_core_ops_text_base(&other) {
        state.facts.view_coalesces.insert(id_of(expr) as i64);
        return check_core_ops_view("str");
    }
    if nullable && inner == check_core_ops_view("str") && !from_a_map && !check_core_ops_index(value) && check_core_ops_variable(fallback) && other.is_a_view() && check_core_ops_text_base(&other) { state.facts.text_view_fallbacks.insert(id_of(expr) as i64); }
    if nullable && !place && inner == check_core_ops_named("String") && !from_a_map && !check_core_ops_index(value) && check_core_ops_variable(fallback) && other.is_a_view() && check_core_ops_text_base(&other) { state.facts.text_owned_fallbacks.insert(id_of(expr) as i64); }
    if nullable && from_a_map && check_core_ops_variable(fallback) && !other.is_a_view() && check_core_ops_held_matches(&inner, &other) && moves(&other) {
        state.facts.lent_map_fallbacks.insert(id_of(expr) as i64);
        return view_of_type(&other);
    }
    if nullable && !from_a_map && inner.is_a_view() && !other.is_a_view() && state.a_package_copy(world, &unviewed_type(&inner)) && state.a_value_written_out(world, fallback) { return unviewed_type(&inner); }
    if nullable && !from_a_map && inner.is_a_view() && !other.is_a_view() && check_core_ops_not_plain(&inner) && state.a_value_written_out(world, fallback) {
        state.facts.lent_map_fallbacks.insert(id_of(expr) as i64);
        return inner;
    }
    if nullable {
        if from_a_map {
            let held = check_core_ops_held(&inner);
            if !check_core_ops_a_map_read_past_a_jump(&state, world, fallback) { state.a_fallback_beside_what_a_map_holds(world, value, &held, &other, span); }
            if held == check_core_ops_named(TEXT) { state.a_fallback_that_owns_what_the_left_side_views(world, &inner, &other, fallback, span); }
        } else { state.a_fallback_that_owns_what_the_left_side_views(world, &inner, &other, fallback, span); }
    }
    if nullable && check_core_ops_own_type(&inner) && !state.jumps(world, fallback) {
        if check_core_ops_a_number_written(fallback) {
            let held = inner.text();
            state.findings.push(check_refusal("NK1103", span, format!("The fallback of this `??` is a number, but the left side holds `{}`.", held), vec![String::from("`a ?? b` is one value, so the fallback is of the type the left side holds (Part I 3.5); a number is not made into another type.")], Some(format!("Write a `{}` as the fallback.", held))));
        } else if !other.is_unknown() && !check_core_ops_nullable(&other) { state.expect_type(world, &other, &inner, span, "let", &|found, wanted| { format!("The fallback of this `??` is `{}`, but the left side holds `{}`.", found, wanted) }); }
    }
    if nullable && !from_a_map && !state.jumps(world, fallback) {
        let held_kind = check_core_ops_kind(&inner);
        let mut given_kind = check_core_ops_kind(&other);
        if check_core_ops_a_number_written(fallback) { given_kind = String::from("number"); }
        if held_kind != "" && given_kind != "" && held_kind != given_kind {
            let held = inner.text();
            let mut given: String = format!("`{}`", other.text());
            if check_core_ops_a_number_written(fallback) { given = String::from("a number"); }
            state.findings.push(check_refusal("NK1103", span, format!("The fallback of this `??` is {}, but the left side holds `{}`.", given, held), vec![String::from("`a ?? b` is one value, so the fallback is of the type the left side holds (Part I 3.5).")], Some(format!("Write a `{}` as the fallback.", held))));
        }
        if held_kind == "number" && given_kind == "number" {
            let held = inner.text();
            let written = check_core_ops_number_written_kind(fallback);
            let held_float = a_float_type(&inner);
            if written == "integer" && held_float || written == "float" && !held_float {
                let mut given: &'static str = "an integer";
                if written == "float" { given = "a float"; }
                state.findings.push(check_refusal("NK1103", span, format!("The fallback of this `??` is {}, but the left side holds `{}`.", given, held), vec![String::from("`a ?? b` is one value, so the fallback is of the type the left side holds (Part I 3.5); an integer and a float are not made into one another (Part I 2.4).")], Some(format!("Write a `{}` as the fallback.", held))));
            } else if written == "" && !inner.is_a_view() && !other.is_a_view() { state.expect_type(world, &other, &inner, span, "let", &|found, wanted| { format!("The fallback of this `??` is `{}`, but the left side holds `{}`.", found, wanted) }); }
        }
    }
    if nullable && check_core_ops_nullable(&other) {
        state.facts.optional_fallbacks.insert(id_of(expr) as i64);
        return other;
    }
    if !nullable { return Ty::Unknown; }
    if inner.is_unknown() && !other.is_unknown() { return other; }
    if !other.is_a_view() { return value_of_a_copy(&inner); }
    inner
}

